import java.util.*;
import java.io.*;

public class Main {
    static int[] match(long[] nuts, long[] bolts) {
        // Write your solution here
        return new int[0];
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        long[] nuts = new long[n], bolts = new long[n];
        for (int i = 0; i < n; i++) {
            in.nextToken();
            nuts[i] = (long) in.nval;
        }
        for (int i = 0; i < n; i++) {
            in.nextToken();
            bolts[i] = (long) in.nval;
        }
        int[] res = match(nuts, bolts);
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < res.length; i++) sb.append(res[i]).append(i + 1 < res.length ? " " : "\n");
        System.out.print(sb);
    }
}
